 if(argc!=2)return 2;const std::filesystem::path out=argv[1];std::filesystem::create_directories(out);Scene scene;auto head_mesh=shell({0,.04f,.05f},{.2f,.2f,.2f});scene.active().painted=std::make_shared<PaintedMesh>(head_mesh,128);scene.active().mesh_active=true;DeformationState reference(head_mesh);Skeleton rig;Bone head;head.name="r0";head.length=.15f;rig.bones.push_back(head);for(float x:{-.05f,.05f}){Bone b;b.name="r"+std::to_string(rig.bones.size());b.parent=0;b.rest.translation={x,.05f,.1f};b.length=.02f;rig.bones.push_back(b);}rig.inverse_bind_override=rig.inverse_bind();reference.skeleton=rig;HumanoidMapping roles;roles.joints={{"head",0},{"leftEye",1},{"rightEye",2}};reference.humanoid=roles;for(const auto&b:rig.bones)reference.pose.push_back(b.rest);reference.pose[0].translation.z=.02f;reference.pose[1].rotation={std::cos(.2f),0,0,std::sin(.2f)};scene.set_deformation(1,reference);scene.active().visible=false;scene.active().locked=true;
 Mesh combined=head_mesh;std::vector<uint32_t>expected_joint(combined.positions.size(),0);auto eye=patch(-.05f,false);const uint32_t offset=uint32_t(combined.positions.size());combined.positions.insert(combined.positions.end(),eye.positions.begin(),eye.positions.end());combined.normals.insert(combined.normals.end(),eye.normals.begin(),eye.normals.end());combined.uv.insert(combined.uv.end(),eye.uv.begin(),eye.uv.end());for(auto v:eye.indices)combined.indices.push_back(v+offset);expected_joint.insert(expected_joint.end(),eye.positions.size(),1);auto raw=combined;unwrap(combined,128,2);std::vector<uint32_t>map(combined.positions.size(),UINT32_MAX);for(size_t c=0;c<combined.indices.size();++c){auto&v=map[combined.indices[c]];if(v!=UINT32_MAX&&v!=raw.indices[c])throw std::runtime_error("Actual new atlas corner source mismatch");v=raw.indices[c];}std::vector<uint32_t>expected;for(auto i:map){if(i>=expected_joint.size())throw std::runtime_error("Unmapped actual native vertex");expected.push_back(expected_joint[i]);}
 auto id=scene.add("Single native mesh with independent head and eye sheets",Volume{});scene.object(id).painted=std::make_shared<PaintedMesh>(combined,128);scene.object(id).mesh_active=true;scene.select(id);const auto before=scene;SkinAuthoringOptions options;options.mode=SkinAuthoringMode::SurfaceHeat;options.reference=1;const std::array targets{id};if(!author_surface_heat_skin(scene,targets,options,{}))throw std::runtime_error("Actual native mixed-component bind required");const auto&d=*scene.object(id).deformation;auto posed=d.preview(combined);double wrong=0,error=0,mean=0;size_t rows=0;for(size_t i=0;i<combined.positions.size();++i)if(expected[i]==1){for(auto x:d.skin->vertices[i])if(x.joint!=1)wrong=std::max(wrong,double(x.weight));auto p=combined.positions[i];const double dx=double(p.x)+.05f,dy=double(p.y)-.05f;auto q=Vec3{float(-.05f+std::cos(.4f)*dx-std::sin(.4f)*dy),float(.05f+std::sin(.4f)*dx+std::cos(.4f)*dy),p.z+.02f};auto v=posed.positions[i]-q;double e=std::hypot(v.x,v.y,v.z);error=std::max(error,e);mean+=e;++rows;}mean/=rows;const double diagonal=std::hypot(.024,.024);const bool pass=wrong==0&&error<=.03*diagonal&&mean<=.01*diagonal;auto retained=scene;retained.object(id).deformation=before.object(id).deformation;retained.object(id).rig_source=before.object(id).rig_source;if(retained.encode()!=before.encode())throw std::runtime_error("Actual mixed-component bind lost paint/UV/reference geometry");scene.save(out/"bound.dsculpt");before.save(out/"unskinned.dsculpt");std::ofstream(out/"report.json")<<nlohmann::json{{"pass",pass},{"eye_rows",rows},{"foreign_weight",wrong},{"max_m",error},{"mean_m",mean},{"local_max",error/diagonal},{"local_mean",mean/diagonal},{"max_bound",.03},{"mean_bound",.01},{"same_geometry_as_separate_qualified_components",true}}.dump(2);std::cout<<(pass?"PASS ":"FAIL ")<<"mixed native components wrong="<<wrong<<" localmax="<<error/diagonal<<" localmean="<<mean/diagonal<<std::endl;return pass?0:1;
